        let manager = SshForwardManager::new(&config).unwrap();
        let observed = Arc::new(AtomicUsize::new(0));
        let mut workers = Vec::new();
        for _ in 0..2 {
            let (stop_tx, stop_rx) = tokio::sync::oneshot::channel::<Instant>();
            let observed = Arc::clone(&observed);
            workers.push((
