  28	impl NativeShutdownCoordinator {
  29	    pub(crate) fn new(
  30	        manager: Arc<SshForwardManager>,
  31	        browser_debug: Arc<BrowserDebugController>,
  32	    ) -> Self {
  33	        Self {
  34	            state: AtomicU8::new(RUNNING),
  35	            manager,
  36	            browser_debug,
  37	        }
  38	    }
  39	
  40	    #[allow(dead_code)]
  41	    pub(crate) fn is_disposed(&self) -> bool {
  42	        self.state.load(Ordering::Acquire) == DISPOSED
  43	    }
  44	
  45	    pub(crate) fn should_prevent_exit(&self) -> bool {
  46	        self.state.load(Ordering::Acquire) != DISPOSED
  47	    }
  48	
  49	    pub(crate) fn begin_disposal(&self) -> bool {
  50	        self.state
  51	            .compare_exchange(RUNNING, DISPOSING, Ordering::AcqRel, Ordering::Acquire)
  52	            .is_ok()
  53	    }
  54	
  55	    pub(crate) fn trigger<R: Runtime>(self: &Arc<Self>, app: AppHandle<R>) {
  56	        self.trigger_with_exit(app, |app| app.exit(0));
  57	    }
  58	
  59	    fn trigger_with_exit<R, F>(self: &Arc<Self>, app: AppHandle<R>, exit: F)
  60	    where
  61	        R: Runtime,
  62	        F: FnOnce(AppHandle<R>) + Send + 'static,
  63	    {
  64	        if !self.begin_disposal() {
  65	            return;
  66	        }
  67	        let coordinator = Arc::clone(self);
  68	        tauri::async_runtime::spawn(async move {
  69	            coordinator.dispose_resources(&app).await;
  70	            exit(app);
  71	        });
  72	    }
  73	
  74	    async fn dispose_resources<R: Runtime>(&self, app: &AppHandle<R>) {
  75	        let deadline = Instant::now() + SHUTDOWN_GRACE;
  76	        let manager = Arc::clone(&self.manager);
  77	        let browser_debug = Arc::clone(&self.browser_debug);
  78	        let cleanup_app = app.clone();
  79	        let cleanup = tauri::async_runtime::spawn_blocking(move || {
  80	            browser_debug.cleanup_on_main_close(&cleanup_app);
  81	        });
  82	        let manager_dispose = async {
  83	            let remaining = deadline.saturating_duration_since(Instant::now());
  84	            let _ = tokio::time::timeout(remaining, manager.dispose()).await;
  85	        };
  86	        let browser_cleanup = async {
  87	            let remaining = deadline.saturating_duration_since(Instant::now());
  88	            let _ = tokio::time::timeout(remaining, cleanup).await;
  89	        };
  90	        tokio::join!(manager_dispose, browser_cleanup);
  91	        self.manager.force_close();
  92	        self.state.store(DISPOSED, Ordering::Release);
  93	    }
  94	
  95	    pub(crate) fn force_close_now(&self) {
  96	        self.manager.force_close();
  97	        self.state.store(DISPOSED, Ordering::Release);
  98	    }
  99	}
